// src/hooks/UseLogs.js
import { useCallback, useEffect, useState } from 'react';
import { fetchLogs, fetchRecentLogs } from '../api/LogsApi';

/**
 * useLogs (명세형)
 * - GET /logs?page&size&from&to&keyword&aiLabel&eventType&sort
 * - fallback: GET /logs/recent?limit=
 *
 * page는 0-based로 운용 (Spring 스타일에 맞춤)
 */
export function useLogs(initialSize = 50) {
  const [size, setSize] = useState(initialSize);
  const [page, setPage] = useState(0);

  const [filters, setFilters] = useState({
    keyword: '',
    aiLabel: '', // SAFE | WARNING | DANGER | ''
    from: '',    // YYYY-MM-DD
    to: '',      // YYYY-MM-DD
    eventType: '',
    sort: 'collectedAt,desc',
  });

  const [logs, setLogs] = useState([]);
  const [total, setTotal] = useState(null); // /logs가 주면 total 채움
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const load = useCallback(async () => {
    const q = { page, size, ...filters };

    setLoading(true);
    setError(null);

    try {
      const res = await fetchLogs(q);
      const items = Array.isArray(res) ? res : res?.items || [];
      setLogs(items);
      setTotal(res?.total ?? null);
    } catch (e) {
      // fallback
      try {
        const fallback = await fetchRecentLogs(size);
        setLogs(Array.isArray(fallback) ? fallback : []);
        setTotal(null);
      } catch (e2) {
        console.error('fetchLogs/fetchRecentLogs error:', e2);
        setError(e2);
      }
    } finally {
      setLoading(false);
    }
  }, [page, size, filters]);

  useEffect(() => {
    load();
  }, [load]);

  const refresh = useCallback(() => load(), [load]);

  // “검색”은 page만 0으로 리셋 (filters는 LogsPage에서 setFilters로 반영)
  const search = useCallback(() => {
    setPage(0);
  }, []);

  // size 변경 시 page도 0으로
  const updateSize = useCallback((nextSize) => {
    setSize(nextSize);
    setPage(0);
  }, []);

  return {
    logs,
    loading,
    error,

    page,
    setPage,
    size,
    setSize: updateSize,
    total,

    // 하위호환(예전 LogsPage가 limit/setLimit 쓰던 부분)
    limit: size,
    setLimit: updateSize,

    // filters
    filters,
    setFilters,

    // actions
    refresh,
    search,
  };
}
